import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Stage 1: many blocks per row. Each block reduces one contiguous chunk
// of a row into a partial sum and partial sum-of-squares. The grid has
// rows * nchunks blocks so every SM is utilized even for few rows.
__global__ void layernorm_partial_kernel(const float* __restrict__ x,
                                         float* __restrict__ p_sum,
                                         float* __restrict__ p_sq,
                                         int64_t N,
                                         int64_t chunk,
                                         int64_t nchunks) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    const int64_t row   = blockIdx.x / nchunks;
    const int64_t c     = blockIdx.x % nchunks;
    const int64_t start = c * chunk;
    int64_t end = start + chunk;
    if (end > N) end = N;
    const float* __restrict__ xr = x + row * N;
    float sum = 0.0f;
    float sq  = 0.0f;
    for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
        float v = xr[i];
        sum += v;
        sq  += v * v;
    }
    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        p_sum[blockIdx.x] = s_sum[0];
        p_sq[blockIdx.x]  = s_sq[0];
    }
}
// Stage 2: each block cheaply re-reduces the small partial arrays of
// its row to get mean / rstd, then normalizes its own chunk.
__global__ void layernorm_normalize_kernel(const float* __restrict__ x,
                                           const float* __restrict__ w,
                                           const float* __restrict__ b,
                                           float* __restrict__ y,
                                           const float* __restrict__ p_sum,
                                           const float* __restrict__ p_sq,
                                           int64_t N,
                                           int64_t chunk,
                                           int64_t nchunks,
                                           float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int64_t row = blockIdx.x / nchunks;
    const int64_t c   = blockIdx.x % nchunks;
    const float* __restrict__ ps = p_sum + row * nchunks;
    const float* __restrict__ pq = p_sq  + row * nchunks;
    float sum = 0.0f;
    float sq  = 0.0f;
    for (int64_t i = threadIdx.x; i < nchunks; i += blockDim.x) {
        sum += ps[i];
        sq  += pq[i];
    }
    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        const float mean = s_sum[0] / (float)N;
        float var = s_sq[0] / (float)N - mean * mean;
        var = var < 0.0f ? 0.0f : var;
        s_mean = mean;
        s_rstd = rsqrtf(var + eps);
    }
    __syncthreads();
    const float mean = s_mean;
    const float rstd = s_rstd;
    const int64_t start = c * chunk;
    int64_t end = start + chunk;
    if (end > N) end = N;
    const float* __restrict__ xr = x + row * N;
    float* __restrict__ yr = y + row * N;
    for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
        yr[i] = (xr[i] - mean) * rstd * w[i] + b[i];
    }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto y = torch::empty_like(x);
    const int64_t rows = x.numel() / normalized_size;
    const int64_t N = normalized_size;
    // Structural fix: the original launch used one block per row, i.e.
    // only `rows` (=16) blocks, leaving most SMs idle. Split each row
    // into `chunks` chunks so the grid fills the device (two-phase
    // reduction over the row).
    const int threads = 256;
    const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    int64_t chunks = ((int64_t)sms * 4 + rows - 1) / rows;
    const int64_t max_chunks = (N + threads - 1) / threads;
    if (chunks > max_chunks) chunks = max_chunks;
    if (chunks < 1) chunks = 1;
    const int64_t chunk = (N + chunks - 1) / chunks;
    chunks = (N + chunk - 1) / chunk;
    auto p_sum = torch::empty({rows * chunks}, x.options());
    auto p_sq  = torch::empty({rows * chunks}, x.options());
    const dim3 grid((unsigned int)(rows * chunks));
    const size_t shmem = 2 * threads * sizeof(float);
    auto stream = at::cuda::getCurrentCUDAStream();
    layernorm_partial_kernel<<<grid, threads, shmem, stream>>>(
        x.data_ptr<float>(),
        p_sum.data_ptr<float>(),
        p_sq.data_ptr<float>(),
        N,
        chunk,
        chunks);
    layernorm_normalize_kernel<<<grid, threads, shmem, stream>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        y.data_ptr<float>(),
        p_sum.data_ptr<float>(),
        p_sq.data_ptr<float>(),
        N,
        chunk,
        chunks,
        (float)eps);
    return y;
}
"""

cpp_src = """
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size);
"""

_ln_mod = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.normalized_size = 1
        for d in self.normalized_shape:
            self.normalized_size *= d
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.contiguous().float()
        w = self.weight
        b = self.bias
        if not w.is_cuda:
            w = w.cuda()
            b = b.cuda()
        w = w.contiguous().view(-1)
        b = b.contiguous().view(-1)
        return _ln_mod.layernorm_forward(
            x, w, b, self.eps, self.normalized_size
        )

